import React, { useState, useEffect, useCallback } from 'react';
import MetricsDashboard from './components/MetricsDashboard';
import InvestigationPanel from './components/InvestigationPanel';
import InvestigationsList from './components/InvestigationsList';

const API = '';  // uses proxy → http://localhost:8000

export default function App() {
  const [tab, setTab] = useState('metrics');
  const [selectedInvId, setSelectedInvId] = useState(null);
  const [triggerResult, setTriggerResult] = useState(null);
  const [triggering, setTriggering] = useState(false);

  const handleTrigger = useCallback(async () => {
    setTriggering(true);
    try {
      const res = await fetch(`${API}/investigations/trigger`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          metric_name: 'retention_rate',
          current_value: 0.31,
          baseline_value: 0.47,
          time_window_days: 7,
        }),
      });
      const data = await res.json();
      setTriggerResult(data);
      setSelectedInvId(data.investigation_id);
      setTab('investigation');
    } catch (e) {
      console.error(e);
    } finally {
      setTriggering(false);
    }
  }, []);

  return (
    <div style={styles.app}>
      {/* Header */}
      <header style={styles.header}>
        <div style={styles.headerLeft}>
          <span style={styles.logo}>⚡ InsightFlow</span>
          <span style={styles.tagline}>Agentic Product Analytics</span>
        </div>
        <button
          onClick={handleTrigger}
          disabled={triggering}
          style={styles.triggerBtn}
          title="Simulate anomaly detection firing an investigation"
        >
          {triggering ? '🔍 Investigating...' : '🚨 Trigger Investigation'}
        </button>
      </header>

      {/* Tabs */}
      <nav style={styles.nav}>
        {[
          { id: 'metrics', label: '📊 Metrics' },
          { id: 'investigations', label: '🔍 Investigations' },
          { id: 'investigation', label: '🧠 Investigation Trace' },
        ].map(t => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            style={{ ...styles.navBtn, ...(tab === t.id ? styles.navBtnActive : {}) }}
          >
            {t.label}
          </button>
        ))}
      </nav>

      {/* Content */}
      <main style={styles.main}>
        {tab === 'metrics' && <MetricsDashboard api={API} />}
        {tab === 'investigations' && (
          <InvestigationsList
            api={API}
            onSelect={(id) => { setSelectedInvId(id); setTab('investigation'); }}
          />
        )}
        {tab === 'investigation' && (
          <InvestigationPanel api={API} investigationId={selectedInvId} />
        )}
      </main>
    </div>
  );
}

const styles = {
  app: {
    fontFamily: "'Inter', 'Segoe UI', system-ui, sans-serif",
    background: '#0f1117',
    color: '#e2e8f0',
    minHeight: '100vh',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '16px 24px',
    background: '#1a1f2e',
    borderBottom: '1px solid #2d3748',
  },
  headerLeft: { display: 'flex', alignItems: 'center', gap: 12 },
  logo: { fontSize: 20, fontWeight: 700, color: '#63b3ed' },
  tagline: { fontSize: 13, color: '#718096' },
  triggerBtn: {
    background: '#e53e3e',
    color: '#fff',
    border: 'none',
    borderRadius: 6,
    padding: '8px 16px',
    cursor: 'pointer',
    fontWeight: 600,
    fontSize: 13,
  },
  nav: {
    display: 'flex',
    gap: 2,
    padding: '8px 24px',
    background: '#151822',
    borderBottom: '1px solid #2d3748',
  },
  navBtn: {
    background: 'transparent',
    color: '#a0aec0',
    border: 'none',
    borderRadius: 6,
    padding: '8px 16px',
    cursor: 'pointer',
    fontSize: 13,
    fontWeight: 500,
  },
  navBtnActive: {
    background: '#2d3748',
    color: '#e2e8f0',
  },
  main: { padding: 24 },
};
